CREATE TABLE public.notification_push_config (id boolean PRIMARY KEY DEFAULT true CHECK(id), token text NOT NULL DEFAULT(gen_random_uuid()::text || gen_random_uuid()::text)); GRANT ALL ON public.notification_push_config TO service_role; REVOKE ALL ON public.notification_push_config FROM anon, authenticated; ALTER TABLE public.notification_push_config ENABLE ROW LEVEL SECURITY; INSERT INTO public.notification_push_config(id) SELECT true; CREATE OR REPLACE FUNCTION public.dispatch_push_on_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_token text; BEGIN SELECT token INTO v_token FROM public.notification_push_config WHERE id=true; IF v_token IS NULL THEN RETURN NEW; END IF; PERFORM net.http_post(url:='https://oylveuwfvsijguwzlauw.supabase.co/functions/v1/send-push',headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_token),body:=jsonb_build_object('notification_id',NEW.id),timeout_milliseconds:=20000); RETURN NEW; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Notification push dispatch failed'; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.dispatch_push_on_notification() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dispatch_push_on_notification() TO service_role; DROP TRIGGER IF EXISTS prod_notifications_push ON public.prod_notifications; DROP TRIGGER IF EXISTS prod_notifications_dispatch_push ON public.prod_notifications; CREATE TRIGGER prod_notifications_dispatch_push AFTER INSERT ON public.prod_notifications FOR EACH ROW EXECUTE FUNCTION public.dispatch_push_on_notification();